import{_ as r,a,b as o,c as n}from"./chunks/3b5380378fc91229ec67.BmcNGAnO.js";import{_ as i,C as l,o as s,c as h,j as e,a as m,E as c,a6 as u}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"互联网已死，而凶手是我们自己","description":"","frontmatter":{"title":"互联网已死，而凶手是我们自己","originalTitle":"The Internet Is Dead, And We Killed It","date":"2025-02-08","originalUrl":"https://thedankoe.com/letters/ai-will-end-the-internet/","minutes":14,"sourceHash":"256f4753ca63a29faf837a56e8cbc60483d47f4ea20481691c295f662455fdca","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/ai-will-end-the-internet/"}]]},"headers":[],"relativePath":"letters/ai-will-end-the-internet.md","filePath":"letters/ai-will-end-the-internet.md"}'),d={name:"letters/ai-will-end-the-internet.md"};function f(A,p,I,_,g,b){const t=l("ArticleMeta");return s(),h("div",null,[p[0]||(p[0]=e("h1",{id:"互联网已死-而凶手是我们自己",tabindex:"-1"},[m("互联网已死，而凶手是我们自己 "),e("a",{class:"header-anchor",href:"#互联网已死-而凶手是我们自己","aria-label":'Permalink to "互联网已死，而凶手是我们自己"'},"​")],-1)),c(t),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/Li-6QMs9_G4?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>根据维基百科（Wikipedia）：</p><blockquote><p>“死亡互联网理论”（Dead Internet Theory）是一种阴谋论，它认为互联网在2016到2017年前后某个时间点“死了”，如今在很大程度上已经被机器人和AI生成的内容所主导，而不是真人。</p></blockquote><p>但关于这个理论，还有一件更令人惊讶的事，没人在谈论。</p><p>说实话，我不知道为什么我们还把这个叫做“阴谋论”。</p><p>互联网上的大部分内容<em>确实</em>是机器人和AI内容组成的。</p><p>而且情况只会越来越严重。</p><p>但说实话，我并不认为这是个问题。</p><p>事实上，这可能是创作者和创业者脱颖而出的最大机会之一。</p><p>另一方面，确实存在无穷无尽的、高度成瘾、让人脑死亡的内容，人们随时随地都可以刷个不停。</p><p>有点离谱的是，普通美国人的平均屏幕使用时间超过<em>7小时！</em>当然，其中一部分可能与工作相关，但我们都知道，即便是在工作时间里，大部分时间也还是花在社交媒体上。</p><p>抑郁、迷茫和压力的报告数量直线飙升，尤其是在AI威胁要取代人类工作的背景下——即便大多数人都说自己讨厌自己的工作——人们还是紧紧抓住这最后一点意义感不肯放手。</p><p>问题是，大多数人根本不想改变。</p><p>人一旦对痛苦习以为常，它就会变得像家一样，反倒是离开它，才让人觉得是真正的煎熬。</p><p>而随着AI每隔一周就刷新一次纪录级的基准测试，个人和公司每天都能量产出成百上千条内容。</p><p>由于这些内容如此让人上瘾，压力、抑郁和迷茫只会越来越严重，我们将无法控制自己。</p><p>问题是：</p><p>这真的<em>算是</em>一个问题吗？</p><p>我们都曾想过……社会真的会变成《机器人总动员》（Wall-E）里那一幕吗？所有人都肥胖不堪，漂浮在椅子上，整天被人不断灌输含糖饮料和娱乐内容？</p><p><em>我不这么确定。</em></p><h2 id="加工内容-vs-有机内容" tabindex="-1">加工内容 VS 有机内容 <a class="header-anchor" href="#加工内容-vs-有机内容" aria-label="Permalink to &quot;加工内容 VS 有机内容&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>加工食品是不好的。</p><p>这很明显，我们都知道。</p><p>但这不意味着我们不能吃一两块饼干——或者在生日那天喝了几杯浓缩马提尼后，凌晨1点一边看老版《办公室》（The Office）一边独自吃掉一整块黄油蛋糕——来平衡一下我们生活中的过度优化。</p><p>问题出现的时候，是我们长时间无法控制自己。</p><p>而这一点，太容易发生了。</p><p>快餐连锁、流媒体公司、游戏公司和社交媒体公司，投入了数千亿美元，去优化那些以多巴胺驱动的反馈循环，目的就是让消费者上瘾。</p><p>光是Facebook（脸书），每年在研发上的投入就超过200亿美元。</p><p>那么，是什么让快餐特别容易让人上瘾呢？就是这个残酷的组合：</p><p>脂肪、糖和盐。</p><p>这些曾是稀缺资源，人类并没有进化出在如今这个世界里应对它们大量存在的能力。我们的进化是为了生存。稀缺的成分一旦被发现，就会向大脑释放多巴胺，示意我们找到了有助于生存的东西。</p><p>一旦各公司发现了这个机制，他们就可以测试并创造出这些成分的组合，最大化地为顾客带来快感，让他们不断回来购买。这就是成瘾。</p><p><img src="'+a+'" alt=""></p><p>互联网公司也如法炮制。它们采用了广告模式来实现盈利，并很快发现，两极分化和煽动性的标题最能吸引注意力。现在，它们只需要把用户“喜欢”的内容源源不断地推送到一个即刻可及的屏幕上就行了。你好，“为你推荐”页面！</p><p>有加工食品，也有加工<em>内容。</em></p><p>数字世界的脂肪、糖和盐。</p><p>廉价的多巴胺。即时满足。熵增。</p><p>快速而肤浅的内容正是如此：熵增性的。你消费得越多，你的思维就变得越混乱。没有长期的意义构建，只有一堆无用的想法填满你的大脑，却没有任何目标或愿景去应用它们。这种数字食物不会给你能量，也不会帮你增肌，它只会让你感觉浑身乏力，只想整天躺着长脂肪。</p><p>作为一个“机器人总动员式”的公民，垂涎于一个精心策划的算法，它不断给你投喂能带来短期满足感的内容，这会让你一直处于压力和求生状态。恐惧和欲望的交织把你从当下拉走，心理熵——也就是心智中的失序——不断增加。你以为那只是一条无害的帖子，实际上它是你连续读到的50条短帖子的组合体，悄无声息地在你心中制造混乱。你退化了。你原地不动。你把自己锁进了某种政治意识形态和僵化观点的范式里，而这些观点根本无法帮你在生活中实现任何有价值的事情。</p><p>悲哀的是……你并不在意，你甚至没意识到自己陷入了这种境地。这就是我写这篇文章的原因。</p><p>但也有一线光明。</p><p>你已经知道，不能指望社交媒体公司自己去改变它们所依赖的激励机制。</p><p>但你可以，也必须，把这件事掌握在自己手里。</p><h3 id="去数字农贸市场购物" tabindex="-1">去数字农贸市场购物 <a class="header-anchor" href="#去数字农贸市场购物" aria-label="Permalink to &quot;去数字农贸市场购物&quot;">​</a></h3><p><a href="https://twitter.com/KevinEspiritu/status/1888066576064332260" target="_blank" rel="noreferrer"><img src="'+o+'" alt=""></a></p><p>在加工食品和加工内容的对立面，存在着有机食品和有机内容。</p><p>“有机”内容是<em>负熵性的（centropic）。</em></p><p>熵增导致失序和混乱，而负熵则相反，它带来秩序和清晰。但你不能指望“为你推荐”页面会主动喂给你这种内容。你必须<em>主动搜索、筛选并培育你的数字信息流</em>，尤其是在AI内容开始泛滥的当下。</p><p>你要如何识别有机内容？</p><ul><li><strong>它是有用的</strong> —— 它能帮助你实现自己的目标。这里有个前提，就是你必须真正拥有自己生成的目标。如果你没有愿景，那么大多数内容——除了那些能帮你产生愿景的内容之外——都是无用的。去读一本哲学书吧。</li><li><strong>它通常是长篇形式的</strong> —— 书籍、文章、时事通讯、播客和YouTube视频。它有足够的空间来传达有意义、有价值的东西。不过，很多短视频创作者也能发布一些洞见和教育内容，作为你心智拼图中的一小块。</li><li><strong>它是真实的</strong> —— 它不是因为“必须发”而被创作出来的，而是因为创作者认为它足够有价值，值得分享给可能从中受益的受众。</li></ul><p>有机的、延迟满足式的内容依然可以运用说服力和吸引注意力的技巧，但它们建立在真实相关的痛点、洞见和教育之上，而不是靠散布恐惧和摧毁大脑。<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">在这里学习如何写这样的内容。</a></p><p>这一切的重点在于，并非所有的社交媒体内容都是坏的。</p><p>事实上，它是一种极其惊人的方式，能让你接触到无穷无尽的知识源泉。你还能在哪里找到那些已经实现了你想要生活的人分享的信息？大多数成功人士都是自学成才的，而如今大部分的自我教育，都是通过屏幕完成的。</p><p>罗马文明中的皇室——比如马可·奥勒留（Marcus Aurelius）——曾能接触到最好的老师，为登上王座做准备。</p><p>现在你已经能在网上接触到最好的老师，你却决定去刷那些又美又蠢的人跳舞的视频？</p><p>这说得通吗？</p><h3 id="为什么ai内容可能是件好事" tabindex="-1">为什么AI内容可能是件好事 <a class="header-anchor" href="#为什么ai内容可能是件好事" aria-label="Permalink to &quot;为什么AI内容可能是件好事&quot;">​</a></h3><p>没人在谈论一个事实：AI生成的内容可能是件好事。</p><p>因为事情是这样的：</p><p>互联网上充斥着大量垂圾内容，这根本不重要。</p><p>这种情况已经存在很多年了。</p><p>更进一步说，如果这真的开始对社交媒体公司的营收构成威胁——而这很可能会发生——他们完全可以创造出一个解决方案。用加密技术做生物识别通行证来证明你是人类，这是一个显而易见的可能方案。</p><p>抱怨“死亡互联网现实”这件事本身很有意思，它能让你分心，不去想你自己能做些什么来应对它。心智在这一点上就是这么狡猾。</p><p>你担心机器人和AI内容影响了你获取优质信息的能力，而事实恰恰相反。你只是想要一切都被喂到你嘴边，而社交媒体公司正好就在给你这个。</p><p>如前所述，我们对痛苦习以为常，它感觉像家一样，而离开它才让人觉得是真正的煎熬。</p><p>除此之外，想想人们实际上是怎么<em>看</em>内容的。</p><p>内容确实海量，这没错。</p><p>但任何一个人能看的帖子数量都是有限的，能关注的人数也是有限的。</p><p>这里的现实是，AI靠自己无法创造出优质内容。</p><p>我试过让它复刻我的写作风格。我设计过简单的提示词，也设计过篇幅堪比一门迷你课程的社交媒体提示词。在AI给我生成的100条帖子里，大概只有<em>一条</em>能直接发出去。剩下的可以作为灵感来源，我会完全重写，有些只需稍作修改，但这里有一个关键点：</p><p>除非<em>你</em>本身擅长做内容，否则AI内容不会好。</p><p>其中大部分都直接沉到了桶底，根本不会被人类的眼睛看到。死亡互联网就像一座冰山，绝大多数死掉的内容都埋得太深，永远不会被任何人看见。</p><p>而且，就算AI生成的内容真的很好，那真的重要吗？</p><p>如果我用AI逐字逐句写出这同一篇通讯，你会在意吗？如果它给了你想要的价值，我敢说你不会在意。你可能会说：“但如果我知道那是AI写的，感觉总有点不对。”</p><p>这种担忧源于对AI本质<em>的</em>根本性误解和过度混淆。炒作最擅长的，就是遮蔽认知。</p><p>智能只是一种资源，而事实证明，它还是一种相当薮弱的资源。如果没有愿景、审美和能动性，它就会失灵。如果你本身不擅长某件事，AI也不会在那件事上变得擅长。</p><p>假设这篇文章是用AI写的。仍然需要一个<em>站在AI背后的人</em>来编排整个故事的讲述方式。这个人需要具备丰富的写作和内容创作经验，才能让输出结果变得<em>好。</em>一句简单的“写一篇关于死亡互联网理论的通讯”指令，根本不可能得出像这篇通讯一样的成果。</p><p>AI并没有取代内容，它只是让制作烂内容变得更容易了。</p><p>事实依然是：如果你没有经验、没有技能，却想用AI快速拿到某个结果，你必然会失败。原理从未改变，也不会改变。</p><blockquote><p>Deep Research刚刚放出了一份疯狂的清单……\\</p><p>OpenAI o3将取代人类的20种职业。<a href="https://t.co/rB45IUqheC" target="_blank" rel="noreferrer">pic.twitter.com/rB45IUqheC</a></p><p>— Min Choi (@minchoi) <a href="https://twitter.com/minchoi/status/1886597182154850546?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2025年2月4日</a></p></blockquote><p>“但是Dan，AI首先会取代的工作岗位，就是社交媒体经理、文案写手和内容营销人员！”</p><p>没错，它们会取代那些套路化的岗位。</p><p>你知道的，那种用Canva做了一张花里胡哨的图片，却给客户带来零效果的社交媒体经理。</p><p>或者那种内容营销人员，在屏幕上放一张漂亮女孩的照片，配上一句人们早就厌倦的Z世代式文案（这种事用Reel Farm已经能自动完成了）。</p><p>又或者那种文案写手，为一家公司写更新动态，仅仅是为了让公司能宣称自己有“线上存在感”。</p><p>把 AI 想象成一个代笔人（或者说是代码代笔、设计代笔、电影代笔等）。</p><p>代笔人不创造故事，他们只是把故事写出来。詹姆斯·帕特森（James Patterson，这对大多数人来说是个震惊的事实）在他的小说里使用代笔人。问题是，詹姆斯仍然掌控着情节、人物、世界观、营销、销售、business，以及其他一切。代笔人只是把这些用文字串联起来。AI 做的正是这件事。不仅是写作，而是上述所有环节，这让帕特森可以完全靠自己一个人完成这一切……如果他想的话。</p><p>现在，重点来了：</p><p>AI 缺乏连贯的愿景和哲学。人们不会因为一篇内容而追随一个创作者。他们追随的是你连贯的作品体系。你不会因为这是你读的第一篇信件就从中找到价值。你找到的价值来自我在过去 3-4 年里编织起来的整套哲学，它帮助特定的、有创造力的个体理清自己在这个世界上的位置。如果你是新来的，你可能会发现一些价值，但读得越多，价值就越会复利叠加。向心聚合（Centropic）。至少这是我的期望。</p><p>好消息是：优秀的作家不会被取代。他们会变得更强大、更有动能。</p><p>人工智能只是创造了一种可能性，让&quot;一个人&quot;能够创造得更多、更快，无论是在公司里还是不在公司里，但前提是这个人重视能动性和自我发展。</p><h2 id="一生难得的机遇" tabindex="-1">一生难得的机遇 <a class="header-anchor" href="#一生难得的机遇" aria-label="Permalink to &quot;一生难得的机遇&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>大多数人不会喜欢这个说法。</p><p>但讽刺的是，唯一的出路就是穿过它。</p><p>要对抗被批量加工的内容洪流，你必须通过发布原生态的内容来为人类做出贡献。</p><p>&quot;为人类做贡献&quot;听起来是句很有力的话，但当社交媒体本身就是媒体，而你就是媒体，媒体塑造文化，文化塑造从政治到经济的一切……那么像&quot;在网上发帖&quot;这样简单的事情，也可能变得相当重要。</p><p>我相信，这是少数几条可行的道路之一：</p><p>成为一个价值创造者。</p><p>这不是什么新鲜事。纵观历史，最快乐、最成功的人都是这样做的。为什么？</p><p>幸福来自于克服阻力，以及与超越自身的某种事物建立联系。换句话说，就是创造和贡献。当你创造时，你解决了一个问题。当你把这个创造物传递给别人时，你解决了他们的问题。当你成为一个有价值可以给予的人，并持续地给予，你就懂得了什么是幸福。</p><p>问题在于，这在过去并不太容易实现。但进化本身就是有创造力的，因此它会解决问题，而这正是一整套酝酿已久的问题：你厌恶的工作、你无法掌控的生活方式，以及缺乏获取机会的途径。</p><p>于是社交媒体作为一种潜在的解决方案登场了。一个被没受过教育的人视为有毒的平台。一个采用了糟糕激励机制、并演化出有趣形态的平台。</p><p>它的好的那一面往往被低估了：</p><ul><li><strong>任何人都可以学习</strong>——你可以随时获取智力资源，尤其是有了 AI 之后。你可以找到实现目标所需的任何信息。</li><li><strong>任何人都可以创造</strong>——你不需要许可就能公开发布你是谁、你在做什么、以及你为什么这样做。</li><li><strong>任何人都可以被发现</strong>——你不再需要出版商、招聘网站或唱片公司才能写书、找工作或做音乐。你的个人品牌就是你的公开简历。</li></ul><p>注意力在社交媒体上。在过去，注意力在广告牌上、在你的本地人际网络里、在广播或电视上。普通人往往没有机会传播自己的作品。</p><p>随着 AI 不断取代入门级工作，而高薪工作被留给了那些技能顶尖的精英（就像进入 NBA 一样，普通人大概是没机会的），前进的道路就在于通才化、能动性和讲故事的能力。</p><h3 id="你就是护城河-如何让自己面向未来" tabindex="-1">你就是护城河（如何让自己面向未来） <a class="header-anchor" href="#你就是护城河-如何让自己面向未来" aria-label="Permalink to &quot;你就是护城河（如何让自己面向未来）&quot;">​</a></h3><p>看起来，人们开始明白我这几年一直在说的事情了。</p><p>不是因为我掌握了什么革命性的信息，而是因为我提出了这个作为潜在解决方案：</p><ul><li><strong>互联网是一个去中心化的教育系统</strong>，创作者是老师，他们能教授相关且有用的信息，其唯一目的并不是把你培养成一个&quot;有用的工人&quot;。</li><li><strong>互联网是公共广场</strong>，你的价值可以在这里被那些需要它的人发现。</li><li><strong>建立受众是新的简历和身份象征。</strong> 关注者不再只是虚荣的数字，而更多是社会证明——证明人们从你的想法中找到了价值。</li><li><strong>任何人都可以成为企业家。</strong> 当学校教育和职业晋升带来的新鲜感和挑战在你二十多岁中期停滞时——导致意义和目标的缺失——创业就是你持续自我发展、掌控未来的方式。</li></ul><p>这不会让一些人感到舒服。</p><p>但听我说。</p><p>我不是在让你去做什么疯狂的事。我只是在提倡自我治理的价值。我在向你展示，有一条路可以让你掌控自己的人生。如果你成为一个创作者，你就不用再担心工作、职业和 AI 的问题了，就像 Naval 会说的那样。</p><p>请意识到，我说的不是&quot;内容创作者&quot;。</p><p>我说的是你存在的本质。</p><p>你是人类。你是创作者。你像一个通才一样构建工具，让自己能在任何环境中生存下来（不像动物只能在一个特定的细分领域中生存）。</p><p>问题是，目前创作者都聚集在互联网上。</p><p>建立受众要求你学习一整套技能，让自己面向未来：能动性、讲故事、说服力、营销、销售、写作，以及如何借助 AI 独自协调你的愿景——所有这些都靠一个人完成。</p><p>这不是那些让人尴尬的内容模板，也不是要在 6 个月内涨到一百万粉丝。</p><p>想想乔丹·彼得森（Jordan Peterson）。</p><p>他不是一个&quot;内容创作者&quot;。他写书。他做演讲。他有自己的写作软件。他有彼得森学院（Peterson Academy），因为学校已经满足不了他的需求。</p><p>互联网和社交媒体，只是<em>推进他一生事业的最佳工具</em>。</p><p>这可能会改变，但真正的创作者会去适应。无论是星际空间、虚拟现实，还是我们退回到石器时代，你都必须成为一个创作者。你必须解决问题并把解决方案分发出去。</p><p>创造出你想要参与其中的互联网。</p><p>创造出你想在这个世界上看到的内容。</p><p>创造出你会购买、使用、并从中受益的产品。</p><p>既然互联网对我们的社会如此重要，你会惊讶地发现，你的贡献能对人类的进步产生多大的影响。放大视角，好好想一想这一点。</p><p>现在，在科技领域，人们经常谈论<em>护城河</em>。</p><p>当 DeepSeek R1（那家中国 AI 公司）以极低的成本、并且开源的方式，构建出一个与 ChatGPT o1 相媲美的出色模型时，人们开始大喊：&quot;根本没有护城河！&quot;</p><p>这意味着没有任何一家公司能独占所有资源。这意味着像智力这样的资源，正在朝着接近零成本、人人可获取的方向发展——就跟建立受众、与任何有网络连接的人建立联系一样。</p><p>这让人们开始疑惑：&quot;那护城河到底是什么？&quot;</p><p>什么才是保护你抵御不确定未来的东西？</p><p>在软件领域，有人说是<em>应用层</em>。</p><p>那些用 AI 构建界面和用例的人，才是真正拥有安全保障的人。他们过去常常因为构建 ChatGPT 套壳应用（一种只是换了个新界面的 ChatGPT 重新包装版软件）而被嘲笑。</p><p>但他们没意识到的是，一切都是套壳。</p><p>Typeform，一家市值数十亿美元的公司，本质上不过是一个 HTML 表单的套壳。</p><p>这就引出了一个问题：终极的套壳是什么？终极的护城河是什么？</p><p><em>你自己。</em></p><p>你就是那个细分领域。</p><p>你的愿景、兴趣、经历、价值观、信念，以及一切构成你之为你的东西，才是你推向世界的任何创作中最独特的套壳。</p><p>为自己而写。</p><p>为自己而建。</p><p>解决你自己的问题，然后把这个解决方案卖出去。</p><p>从各方面来看，这是让自己面向未来的唯一方法。</p><p>其他一切都只是分心的东西。</p><p>——丹（Dan）</p><p>如果你想学习我的写作系统，用它来建立一群支持你事业的受众，可以看看 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>。</p><p>如果你想学习现代商业的基础知识，可以看看 <a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">一人企业启动台（One-Person Business Launchpad）</a>。</p><p>如果你想找一个地方来捕捉想法、建立第二大脑，并发现你自己究竟有多独特，<a href="https://kortex.co/" target="_blank" rel="noreferrer">开始在 Kortex 里写作吧。</a></p><hr><p><a href="/en/letters/ai-will-end-the-internet">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',153))])}const P=i(d,[["render",f]]);export{T as __pageData,P as default};
